using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    private static readonly Dictionary<string,Vector2> ExtraEffectRanges=new(){["emboss"]=new(0,4),["edge_detect"]=new(0,4),["motion_blur"]=new(0,64),["radial_blur"]=new(0,32),["kaleidoscope"]=new(2,16),["ripple"]=new(0,40),["scanlines"]=new(0,1)};
    private static readonly Dictionary<string,Vector2> EffectRanges=new(){["brightness"]=new(-1,1),["contrast"]=new(0,3),["saturation"]=new(0,3),["blur"]=new(0,24),["sharpen"]=new(0,2),["outline"]=new(0,24),["shadow"]=new(0,24),["glow"]=new(0,32),["wave"]=new(0,40),["twirl"]=new(-12,12),["chromatic"]=new(0,32),["grain"]=new(0,1),["pixelate"]=new(1,128),["halftone"]=new(2,64),["posterize"]=new(2,32),["vignette"]=new(0,2),["color_replace"]=new(.001f,1)};
    public void effect_fields(Control owner,Node fields,Settings effect)
    {
        string type=Get(effect,"type","").AsString();if(type=="emboss")check(owner,fields,"Preserve color",Get(effect,"preserve_color",false).AsBool(),Callable.From<bool>(value=>effect["preserve_color"]=value));
        void Amount(Vector2 limits)=>slider(owner,fields,"Amount",Get(effect,"amount",1).AsDouble(),limits.X,limits.Y,Callable.From<double>(value=>effect["amount"]=value));
        if(ExtraEffectRanges.TryGetValue(type,out var extra))Amount(extra);if(type is "motion_blur" or "kaleidoscope")slider(owner,fields,"Angle",Get(effect,"angle",0).AsDouble(),-180,180,Callable.From<double>(value=>effect["angle"]=value));if(type is "ripple" or "scanlines")slider(owner,fields,type=="ripple"?"Frequency":"Line spacing",Get(effect,"spacing",12).AsDouble(),1,64,Callable.From<double>(value=>effect["spacing"]=value));if(EffectRanges.TryGetValue(type,out var range))Amount(range);
        if(type is "outline" or "shadow" or "glow" or "gradient_map" or "color_replace")color(owner,fields,"Start / target",Get(effect,"color",Colors.Black).AsColor(),Callable.From<Color>(value=>effect["color"]=value));if(type is "gradient_map" or "color_replace")color(owner,fields,"End / replacement",Get(effect,"color2",Colors.White).AsColor(),Callable.From<Color>(value=>effect["color2"]=value));
        if(type=="shadow")foreach(int component in new[]{0,1}){int axis=component;number(owner,fields,axis==0?"Offset X":"Offset Y",effect["offset"].AsVector2()[axis],Callable.From<double>(value=>{var offset=effect["offset"].AsVector2();offset[axis]=(float)value;effect["offset"]=offset;}),-128,128,.1);}if(type=="mirror")owner.Call("_mirror_fields",fields,effect);if(type=="shader"&&Get(effect,"shader").VariantType==Variant.Type.Object&&Get(effect,"shader").AsGodotObject() is Shader)owner.Call("_shader_fields",fields,effect);if(type=="curves")curve_effect_fields(owner,fields,effect);
    }
    public void curve_effect_fields(Control owner,Node fields,Settings effect)
    {
        var channel=new OptionButton{Name="CurveChannel"};foreach(string caption in new[]{"Overall RGB","Red","Green","Blue","Alpha"})channel.AddItem(caption);fields.AddChild(channel);string[] keys={"master","red","green","blue","alpha"};var script=GD.Load<GDScript>("res://Workspaces/SceneWorkspace/scripts/Timeline/actor_value_curve.gd");var graph=script.New().As<Control>();graph.Set("editable",true);graph.CustomMinimumSize=new Vector2(0,150);fields.AddChild(graph);
        Curve Linear()=>script.Call("preset","Linear").As<Curve>();void Update(){string key=keys[channel.Selected];graph.Set("curve",key=="master"?Get(effect,"curve",Linear()):Get(Get(effect,"curves",new Settings()).AsGodotDictionary(),key,Linear()));graph.QueueRedraw();}channel.ItemSelected+=_=>Update();Update();graph.Connect("edit_started",Callable.From(()=>begin(owner)));graph.Connect("preview_changed",Callable.From<Curve>(curve=>{if(channel.Selected==0)effect["curve"]=curve;else{if(!effect.ContainsKey("curves"))effect["curves"]=new Settings();effect["curves"].AsGodotDictionary()[keys[channel.Selected]]=curve;}preview(owner);}));graph.Connect("edit_committed",Callable.From(()=>commit(owner)));graph.Connect("edit_cancelled",Callable.From(()=>cancel(owner)));var reset=new Button{Text="Reset channel",TooltipText="Reset the selected curve",Icon=icon(owner,"reset"),ExpandIcon=true,FocusMode=Control.FocusModeEnum.None,CustomMinimumSize=new Vector2(0,32)};reset.AddThemeConstantOverride("icon_max_width",18);fields.AddChild(reset);reset.Pressed+=()=>{Action(owner,()=>{if(channel.Selected==0)effect["curve"]=Linear();else if(effect.ContainsKey("curves"))effect["curves"].AsGodotDictionary().Remove(keys[channel.Selected]);});Update();};
    }
}
